mapper.sql:
s.PRINCIPAL_NAME ~ '^[0-9]+$'
and s.EXPIRY_TIME > #{nowEpochMillis}

  and (

      cast(s.PRINCIPAL_NAME as bigint) = #{query.keywordUserId}
      or

    lower(coalesce(u.email_normalized, '')) like concat('%', lower(#{query.keyword}), '%')
    or lower(coalesce(u.display_name, '')) like concat('%', lower(#{query.keyword}), '%')
  )


  and s.LAST_ACCESS_TIME >= #{activeSinceEpochMillis}


  and s.LAST_ACCESS_TIME < #{activeSinceEpochMillis}

mapper.select:
select 
from SPRING_SESSION s
left join auth_users u on u.id = cast(s.PRINCIPAL_NAME as bigint)
where s.PRIMARY_ID = #{sessionRef}
  and s.PRINCIPAL_NAME ~ '^[0-9]+$'
  and s.EXPIRY_TIME > #{nowEpochMillis}
